// components/Login.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEnvelope, faLock } from '@fortawesome/free-solid-svg-icons';
import './Login.css';
import PageTitle from '../PageTitle';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    // API'ye post isteği gönderme
    try {
      const response = await fetch('http://localhost:5000/api/users/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        // Giriş başarılı, admin paneline yönlendir
        localStorage.setItem('token', data.token);  // JWT token'ı localStorage'a kaydet
        navigate('/admin');  // Admin paneline yönlendir
      } else {
        setError(data.message); // Hata mesajını göster
      }
    } catch (error) {
      setError('Bir hata oluştu. Lütfen tekrar deneyin.');
    }
  };

  return (
    <>
      <PageTitle title="Giriş Yap" />
      <div className="loginpage">
        <div className="container">
          <div className="row">
            <div className="col-sm-12">
              <div className="loginlogo">Beeonhive</div>
            </div>
          </div>
        </div>
        <div className="turnhome">
          <a href="/"><b>Ana Sayfaya Dön</b></a>
        </div>
        <div className="card">
          <div className="logincard">
            <div className="logincardbody">
              <p className="login-box-msg">Oturumunuzu başlatmak için giriş yapın</p>
            </div>
            {error && <p className="error-message">{error}</p>}
            <form onSubmit={handleSubmit}>
              <div className="input-group">
                <input
                  type="email"
                  id="email"
                  className="email"
                  placeholder="E-mail"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
                <span className="icon-group icon-group-email">
                  <FontAwesomeIcon icon={faEnvelope} className="icon-small" />
                </span>
              </div>
              <div className="input-group">
                <input
                  type="password"
                  id="password"
                  className="formcontrol"
                  placeholder="Şifre"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <span className="icon-group icon-group-password">
                  <FontAwesomeIcon icon={faLock} className="icon-small" />
                </span>
              </div>
              <div className="row">
                <div className="col-6">
                  <button type="submit" id="btngiris" className="btngirisyap">Giriş Yap</button>
                </div>
              </div>
            </form>
            <p className="sifremiunuttum">
              <a href="" target="_blank">Şifremi unuttum</a>
            </p>
          </div>
        </div>
      </div>
    </>
  );
}

export default Login;
